export class AudioEngine {
  constructor(){this.enabled=true;this.ctx=null;this.ambient=null;}
  init(){if(this.ctx){this.ctx.resume().catch(()=>{});return;}const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;this.ctx=new AC();this.master=this.ctx.createGain();this.master.gain.value=this.enabled?.2:0;this.master.connect(this.ctx.destination);for(const [freq,gain] of [[46,.14],[69,.06],[138,.018]]){const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='sine';o.frequency.value=freq;g.gain.value=gain;o.connect(g).connect(this.master);o.start();}this.ctx.resume().catch(()=>{});}
  toggle(){this.enabled=!this.enabled;if(this.ctx)this.master.gain.setTargetAtTime(this.enabled?.2:0,this.ctx.currentTime,.1);return this.enabled;}
  tone(freq,end,duration,volume=.25,type='sine',delay=0){if(!this.ctx)return;const t=this.ctx.currentTime+delay,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(1,end),t+duration);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(volume,t+.012);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g).connect(this.master);o.start(t);o.stop(t+duration+.02);}
  play(type){if(type==='pulse'){this.tone(740,200,1.5,.5);this.tone(370,100,1.8,.2,'sine',.16);}if(type==='dash')this.tone(90,360,.22,.28,'triangle');if(type==='shard'){this.tone(660,880,.18,.15);this.tone(990,1320,.25,.12,'sine',.08);}if(type==='air'){this.tone(220,440,.4,.2);this.tone(330,660,.6,.12,'sine',.12);}if(type==='hit'){this.tone(75,28,.45,.8,'triangle');this.tone(135,45,.15,.3,'sawtooth');}if(['core','upgrade','won','sector'].includes(type)){[261.63,329.63,392,523.25].forEach((n,i)=>this.tone(n,n*1.002,1.3,.24,'sine',i*.13));}if(type==='lost')this.tone(120,25,2,.4);}
}
